function smallestEqual(nums) {
  const matches = [];
  nums.forEach((value, index) => {
    const lastDigit = Number(String(index).slice(-1));
    if (lastDigit === value) matches.push(index);
  });
  return matches.length ? Math.min(...matches) : -1;
}

