function generate(rand, size) {
  const n = size === 'large' ? 100 : 1 + Math.floor(rand() * 25);
  const mode = rand();
  const nums = [];
  for (let i = 0; i < n; i++) {
    if (mode < 0.45) {
      // A value that never matches its own position.
      nums.push((i % 10 + 1 + Math.floor(rand() * 9)) % 10);
    } else {
      nums.push(Math.floor(rand() * 10));
    }
  }
  // Sometimes plant a single match somewhere in a no-match array.
  if (mode < 0.3) {
    const at = Math.floor(rand() * n);
    nums[at] = at % 10;
  }
  return [nums];
}
